from math import erf, exp, log, sqrt

def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def down_and_out_formula(S0, K, B, r, sigma, T):
    """Continuously monitored down-and-out call, for B <= K."""
    if B >= S0:
        return 0.0
    d1 = (log(S0 / K) + (r + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    vanilla = S0 * norm_cdf(d1) - K * exp(-r * T) * norm_cdf(d1 - sigma * sqrt(T))
    lam = (r + sigma ** 2 / 2) / sigma ** 2
    y = log(B ** 2 / (S0 * K)) / (sigma * sqrt(T)) + lam * sigma * sqrt(T)
    c_in = (S0 * (B / S0) ** (2 * lam) * norm_cdf(y)
            - K * exp(-r * T) * (B / S0) ** (2 * lam - 2) * norm_cdf(y - sigma * sqrt(T)))
    return vanilla - c_in

def bgk_barrier(B, sigma, dt):
    """Barrier moved away from the share for discrete monitoring."""
    return B * exp(-0.5826 * sigma * sqrt(dt))
